FED-001 lives at `/home/kara/sqlite-idempotent-migration-adapter-chain/`. The fix is a **ledger-based migrator + guarded primitive helpers** written against a minimal 4-method adapter contract (`all/run/exec/close`), so one migration set runs unchanged on all four backends.

**Adapter contract** (`src/adapter.js`) — `PRAGMA table_info` is read through `adapter.all`, which works on all 4 backends:

```js
// better-sqlite3 / node:sqlite  (identical bodies)
all(sql, params = []) { return db.prepare(sql).all(...params); }
// bun:sqlite
all(sql, params = []) { return db.query(sql).all(...params); }
// sql.js (prepare/step/getAsObject loop — no column quirk)
all(sql, params = []) { const s = db.prepare(sql); try {
    if (params.length) s.bind(params);
    const rows = []; while (s.step()) rows.push(s.getAsObject()); return rows;
  } finally { s.free(); } }
```

**Guarded primitives** (`src/guard.js`) — the idempotency core. Names are regex-validated before interpolation because PRAGMA can't take bound params on every backend:

```js
export function columnExists(adapter, table, column) {
  assertIdentifier(table, 'table name'); assertIdentifier(column, 'column name');
  return adapter.all(`PRAGMA table_info(${table})`)   // [] if column missing
    .some((row) => String(row.name) === column);
}
export function addColumnIfMissing(adapter, table, column, columnDdl) {
  if (!columnExists(adapter, table, column))
    adapter.run(`ALTER TABLE ${table} ADD COLUMN ${columnDdl}`);
}
export function insertOrIgnore(adapter, table, row) {
  /* INSERT OR IGNORE ... VALUES (?...) — PK/UNIQUE makes seeds idempotent */
}
```

**Migration 002** (`src/migrations.js`) — guarded ALTERs, `CREATE TABLE IF NOT EXISTS`, `INSERT OR IGNORE` seeds:

```js
export const migration002 = {
  id: '002-federation',
  up(adapter) {
    addColumnIfMissing(adapter, 'apps', 'federation_role', `federation_role TEXT NOT NULL DEFAULT 'origin'`);
    addColumnIfMissing(adapter, 'apps', 'federation_hub', 'federation_hub TEXT');
    addColumnIfMissing(adapter, 'models', 'federation_enabled', 'federation_enabled INTEGER NOT NULL DEFAULT 0');
    addColumnIfMissing(adapter, 'providers', 'federation_priority', 'federation_priority INTEGER NOT NULL DEFAULT 0');
    addColumnIfMissing(adapter, 'routers', 'federation_zone', `federation_zone TEXT NOT NULL DEFAULT 'local'`);
    addColumnIfMissing(adapter, 'kv', 'ttl_seconds', 'ttl_seconds INTEGER');
    createTableIfNotExists(adapter, `CREATE TABLE IF NOT EXISTS federation_peers (
      id TEXT PRIMARY KEY, peer_url TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'edge',
      health INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')))`);
    insertOrIgnore(adapter, 'kv', { scope: 'pricing',      key: 'default', value: '{"per_million_tokens":0.50,"currency":"USD"}' });
    insertOrIgnore(adapter, 'kv', { scope: 'modelAliases', key: 'hub',     value: 'http://localhost:8787' });
    insertOrIgnore(adapter, 'federation_peers', { id: 'self', peer_url: 'http://localhost:8787', role: 'hub', health: 1 });
  },
};
```

**Spec mapping (8 logical → 7 physical):** physical = `apps models providers routes deployments routers kv`; `modelAliases` and `pricing` are **kv scope rows** (`kv.scope`), never tables.

**Migrator:** `_migrations(id, applied_at)` ledger; each migration runs once, in a `BEGIN/COMMIT` transaction with the ledger entry — a failed migration rolls back atomically.
